import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, SpotLight, Object3D } = ctx.THREE;

  /** Root object – positioned by the adapter */
  const root = new Group();

  /** Keep track of disposables */
  const disposers = [];
  const timelines = [];

  /* -------------------------------------------------
   * Load the GLB mesh (materials are baked in)
   * ------------------------------------------------- */
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;
      root.add(model);
      disposers.push(() => {
        model.traverse((c) => {
          if (c.isMesh) {
            c.geometry?.dispose?.();
            c.material?.dispose?.();
          }
        });
      });
    });
  }

  /* -------------------------------------------------
   * Accent rim light (signal red)
   * ------------------------------------------------- */
  const accentHex =
    (config.colors?.accent ??
      config.visualSpec?.colors?.accent ??
      '#ff2a38');
  const rimLight = new SpotLight(accentHex, 0.6);
  rimLight.position.set(0, 0, 1);
  rimLight.castShadow = false;
  root.add(rimLight);
  disposers.push(() => rimLight.dispose());

  /* -------------------------------------------------
   * Cinematic primitives
   * ------------------------------------------------- */
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const instance = fn(root, prim.params ?? {});
        if (instance) {
          if (instance.timeline) timelines.push(instance.timeline);
          if (instance.cleanup) disposers.push(instance.cleanup);
        }
      }
    });
  }

  /* -------------------------------------------------
   * Interaction handlers
   * ------------------------------------------------- */
  root.userData.handlers = {};

  // Hover – subtle rise‑in (0.15 scene units)
  const hoverEnter = () => {
    const tl = gsap.timeline({ paused: false });
    tl.to(
      root.position,
      { y: root.position.y + 0.15, duration: 0.15, ease: 'power2.out' },
    );
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.timeline({ paused: false });
    tl.to(
      root.position,
      { y: root.position.y - 0.15, duration: 0.15, ease: 'power2.in' },
    );
    timelines.push(tl);
  };
  root.userData.handlers.hoverEnter = hoverEnter;
  root.userData.handlers.hoverLeave = hoverLeave;

  // Click – emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-collection.select');
  };

  /* -------------------------------------------------
   * Cleanup
   * ------------------------------------------------- */
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill && tl.kill());
    timelines.length = 0;

    // Dispose primitives/resources
    disposers.forEach((fn) => fn && fn());
    disposers.length = 0;

    // Remove children (in case something was added after load)
    root.traverse((c) => {
      if (c.isMesh) {
        c.geometry?.dispose?.();
        c.material?.dispose?.();
      }
    });
  };

  return root;
}
